    for j in possible_birthdays:
        if month == j[0]:
            month_day = month_day + (j,)
    for t in month_day:
        if unique_day(t[1], possible_birthdays) == True:
            return True
    return False

def unique_day(day, possible_birthdays):
    count = 0
    for i in range(len(possible_birthdays)):
        if day == possible_birthdays[i][1]:
            count += 1
    if count != 1:
        return False
    return True

